using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens; using MotoHubAPI.Data; using MotoHubAPI.DTOs; using MotoHubAPI.Models;
namespace MotoHubAPI.Controllers;
[ApiController,Route("api/auth")]
public class AuthController(MotoHubDbContext db,IConfiguration config) : ControllerBase {
 [HttpPost("register")] public async Task<IActionResult> Register(RegisterRequest r) { if(await db.Users.AnyAsync(x=>x.Email==r.Email.Trim().ToLower())) return Conflict(new{message="Email is already registered."}); var u=new AppUser{FullName=r.FullName.Trim(),Email=r.Email.Trim().ToLower(),Role="Customer"}; u.PasswordHash=new PasswordHasher<AppUser>().HashPassword(u,r.Password); db.Users.Add(u); await db.SaveChangesAsync(); return Created("",new{id=u.Id,u.FullName,u.Email,u.Role}); }
 [HttpPost("login")] public async Task<IActionResult> Login(LoginRequest r) { var u=await db.Users.SingleOrDefaultAsync(x=>x.Email==r.Email.Trim().ToLower()); if(u is null || new PasswordHasher<AppUser>().VerifyHashedPassword(u,u.PasswordHash,r.Password)==PasswordVerificationResult.Failed) return Unauthorized(new{message="Invalid email or password."}); var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.FullName),new Claim(ClaimTypes.Email,u.Email),new Claim(ClaimTypes.Role,u.Role)}; var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]!)); var token=new JwtSecurityToken(config["Jwt:Issuer"],config["Jwt:Audience"],claims,expires:DateTime.UtcNow.AddHours(4),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256)); return Ok(new{token=new JwtSecurityTokenHandler().WriteToken(token),user=new{id=u.Id,u.FullName,u.Email,u.Role}}); }
}
